function SparkMark({ size = 18, color }) {
  const c = color || TOKENS.text;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M12 2 L12 22 M2 12 L22 12 M5.5 5.5 L11 11 M18.5 18.5 L15 15" stroke={c} strokeWidth="1.4" strokeLinecap="round" />
    </svg>
  );
}

function GlowArc() {
  const [drawn, setDrawn] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setDrawn(true), 250);
    return () => clearTimeout(t);
  }, []);
  return (
    <svg
      viewBox="0 0 600 300"
      style={{
        position: "absolute",
        top: -20,
        right: -40,
        width: 480,
        height: 240,
        pointerEvents: "none",
        opacity: 0.55,
        zIndex: 0,
      }}
      aria-hidden="true"
    >
      <path
        d="M 40 260 C 220 260, 340 220, 540 40"
        fill="none"
        stroke={TOKENS.amber}
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeDasharray="640"
        strokeDashoffset={drawn ? 0 : 640}
        style={{ transition: "stroke-dashoffset 1.8s ease" }}
      />
      <circle
        cx="540"
        cy="40"
        r={drawn ? 5 : 0}
        fill={TOKENS.amber}
        style={{ transition: "r 0.4s ease 1.6s", filter: `drop-shadow(0 0 8px ${TOKENS.amber})` }}
      />
    </svg>
  );
}

